async function renderCustomInto(output:ExcelWorkbook,body:Blob,snapshot:ProjectDocumentationSnapshot,table:ProjectDocumentationTable,worksheetName:string):Promise<void>{const section=snapshot.set.sections.find(({id})=>id===table.id)!;const validation=await validateExcelTemplateWorkbook(body,section.kind);if(!validation.valid)throw new Error(validation.findings.map(({location,message})=>`${location}: ${message}`).join("\n"));const source=new (excelJs().Workbook)();await source.xlsx.load(await body.arrayBuffer());const worksheet=source.getWorksheet?.("Template")??source.worksheets.find(({name})=>name==="Template")!,prototype=prototypeFromWorkbook(source,section.kind),context=prepareDocumentationTemplateContext(snapshot,table.id),rendered=renderExcelTemplateGrid(prototype,context),target=output.addWorksheet(worksheetName);for(const cell of rendered.cells){const destination=target.getCell(cell.address),sourcePoint=cellPoint(cell.sourceAddress??cell.address),targetPoint=cellPoint(cell.address);destination.value=cell.value;destination.style=structuredClone(cell.style??{});if(cell.note)destination.note=structuredClone(cell.note);const sourceRow=worksheet.getRow(sourcePoint.row);if(sourceRow.height!==undefined)target.getRow(targetPoint.row).height=sourceRow.height;const sourceColumn=worksheet.getColumn(sourcePoint.column),targetColumn=target.getColumn(targetPoint.column);if(sourceColumn.width!==undefined)targetColumn.width=sourceColumn.width;if(sourceColumn.hidden!==undefined)targetColumn.hidden=sourceColumn.hidden;if(sourceColumn.outlineLevel!==undefined)targetColumn.outlineLevel=sourceColumn.outlineLevel;}for(const merge of rendered.merges)target.mergeCells(merge);target.pageSetup=structuredClone(worksheet.pageSetup);target.headerFooter=structuredClone(worksheet.headerFooter);copyImages(source,worksheet,output,target,rendered,prototype,context);}
